function ProjectsPage() {
  const [filter, setFilter] = useState('All');
  const [status, setStatus] = useState('All');
  const [location, setLocation] = useState('All');
  const [items] = useStored<Project[]>('nestood_projects', seedProjects);
  const filters = ['All','Residential','Commercial','Villa','Renovation'];
  const visible = items.filter(item => (filter==='All'||item.category===filter) && (status==='All'||item.status===status) && (location==='All'||item.location.includes(location)));
  return <PublicShell><PageIntro eyebrow="Projects" title={<>Good spaces<br /><em>hold a feeling.</em></>} copy="A selection of homes, workplaces and renovations. Every project is a record of a brief made real." /><section className="section-pad bg-[#F8F8F5]"><div className="site-shell"><div className="flex flex-wrap gap-2">{filters.map(item=><button type="button" key={item} onClick={()=>setFilter(item)} className={`border px-4 py-2.5 text-[10px] font-bold uppercase tracking-[.14em] ${filter===item?'border-[#222B52] bg-[#222B52] text-[#F8F8F5]':'border-[#222B52]/20 text-[#6B7280]'}`} data-testid={`button-project-filter-${item.toLowerCase()}`}>{item}</button>)}<select value={status} onChange={e=>setStatus(e.target.value)} className="border border-[#222B52]/20 bg-transparent px-4 py-2 text-[10px] font-bold uppercase tracking-[.14em] text-[#6B7280]" data-testid="select-project-status"><option>All</option><option>Completed</option><option>Ongoing</option></select><select value={location} onChange={e=>setLocation(e.target.value)} className="border border-[#222B52]/20 bg-transparent px-4 py-2 text-[10px] font-bold uppercase tracking-[.14em] text-[#6B7280]" data-testid="select-project-location"><option>All</option><option>Chennai</option><option>Bengaluru</option></select></div><div className="mt-14 grid gap-x-6 gap-y-12 sm:grid-cols-2 lg:grid-cols-3">{visible.map((project,i)=><Link href={`/projects/${project.slug}`} key={project.id} className="group" data-testid={`card-project-${project.id}`}><Visual name={project.name} label={`${project.status} · ${project.completion}`} className={i%3===1?'min-h-[260px]':''}/><div className="mt-5 flex justify-between"><div><h2 className="font-editorial text-[28px] leading-none text-[#222B52]">{project.name}</h2><p className="mt-2 text-xs text-[#6B7280]">{project.location} · {project.area}</p></div><ArrowUpRight size={17} className="text-[#0C4A46] transition-transform group-hover:-translate-y-1 group-hover:translate-x-1"/></div></Link>)}</div>{!visible.length&&<div className="mt-10 border border-dashed border-[#222B52]/20 py-16 text-center text-sm text-[#6B7280]">No projects match those filters.</div>}</div></section></PublicShell>;
}
function ProjectDetailPage() {
  const { slug } = useParams<{ slug: string }>();
  const [items] = useStored<Project[]>('nestood_projects', seedProjects);
  const project = items.find(item => item.slug === slug) ?? seedProjects[0];
  return <PublicShell><section className="bg-[#222B52] pb-16 pt-32 text-[#F8F8F5]"><div className="site-shell"><Link href="/projects" className="inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.16em] text-[#A5C7C1]" data-testid="link-back-projects"><ArrowLeft size={15}/> Back to projects</Link><div className="mt-14 grid gap-10 lg:grid-cols-[1fr_.9fr] lg:items-end"><div><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#A5C7C1]">{project.category} / {project.status}</p><h1 className="mt-5 font-editorial text-[clamp(4rem,8vw,8rem)] leading-[.8]">{project.name}</h1></div><p className="max-w-[400px] text-[15px] leading-7 text-[#F8F8F5]/65">{project.description}</p></div></div></section><section className="section-pad bg-[#F8F8F5]"><div className="site-shell"><div className="grid gap-5 md:grid-cols-3"><Visual label="01 / Arrival" name={project.name} className="min-h-[360px]"/><Visual label="02 / Material study" name="Material study" className="min-h-[360px]"/><Visual label="03 / Living detail" name="Built for real life" className="min-h-[360px]"/></div><div className="mt-20 grid gap-12 lg:grid-cols-[.75fr_1.25fr]"><div className="grid grid-cols-2 gap-y-8 border-t border-[#222B52]/20 pt-6">{[['Location',project.location],['Area',project.area],['Project cost',project.cost],['Completion',project.completion],['Status',project.status],['Category',project.category]].map(([label,value])=><div key={label}><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#6B7280]">{label}</p><p className="mt-2 text-sm text-[#222B52]">{value}</p></div>)}</div><div><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]">Specifications</p><h2 className="mt-5 font-editorial text-5xl text-[#222B52]">A place shaped by its <em>brief.</em></h2><p className="mt-6 max-w-[600px] text-lg leading-8 text-[#6B7280]">{project.specs}. Every choice was tested against the way the home would be used, maintained and lived in over time.</p><Button href="/contact">Talk about your project</Button></div></div></div></section></PublicShell>;
}

function LocationsPage() {
  const [items] = useStored<LocationRecord[]>('nestood_locations', seedLocations);
  return <PublicShell><PageIntro eyebrow="Locations" title={<>Local knowledge.<br /><em>One standard.</em></>} copy="Our teams work where they can stay close to the site. That means better decisions, calmer coordination and a partner who understands the local context." /><section className="section-pad bg-[#FFF]"><div className="site-shell grid gap-5 md:grid-cols-2">{items.map((item,i)=><article key={item.id} className="border border-[#222B52]/15 p-8"><Visual label={`0${i+1} / city` } name={`${item.city} build desk`} className="min-h-[220px]" /><h2 className="mt-10 font-editorial text-6xl text-[#222B52]">{item.city}</h2><p className="mt-5 text-sm leading-6 text-[#6B7280]">{item.description}</p><div className="mt-8 border-t border-[#222B52]/15 pt-6"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]">Areas served</p><p className="mt-3 text-sm text-[#6B7280]">{item.areas}</p><p className="mt-6 text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]">Local construction range</p><p className="mt-3 font-editorial text-3xl text-[#222B52]">{item.pricing}</p><p className="mt-6 text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]">Services</p><p className="mt-3 text-sm text-[#6B7280]">{item.services}</p></div><Link href="/contact" className="mt-9 inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]" data-testid={`link-location-enquiry-${item.id}`}>Enquire in {item.city} <ArrowUpRight size={15}/></Link></article>)}</div></section></PublicShell>;
}

function TestimonialsPage() {
  const [items] = useStored<Testimonial[]>('nestood_testimonials', seedTestimonials);
  const [active, setActive] = useState(0);
  const item = items[active % items.length];
  return <PublicShell><PageIntro eyebrow="Testimonials" title={<>The best part is hearing <em>what stays.</em></>} copy="A construction project ends at handover. The relationship, the routines and the feeling of the place carry on." dark /><section className="section-pad bg-[#F8F8F5]"><div className="site-shell"><div className="grid gap-12 lg:grid-cols-[.8fr_1.2fr]"><Visual label="Client story" name={item.project} className="min-h-[420px]" /><div className="flex flex-col justify-between"><div><div className="flex gap-1 text-[#0C4A46]">{Array.from({length:5}).map((_,i)=><Star key={i} size={16} fill={i<item.rating?'currentColor':'none'}/>)}</div><blockquote className="mt-8 font-editorial text-[clamp(2.8rem,5vw,5rem)] leading-[.9] text-[#222B52]">“{item.review}”</blockquote><p className="mt-8 text-[10px] font-bold uppercase tracking-[.16em] text-[#6B7280]">{item.customer} · {item.project} · {item.location}</p><p className="mt-4 text-xs text-[#6B7280]">{item.media}</p></div><div className="mt-12 flex items-center gap-3"><button type="button" onClick={()=>setActive((active-1+items.length)%items.length)} className="flex h-10 w-10 items-center justify-center border border-[#222B52]/25 text-[#222B52]" data-testid="button-testimonial-prev"><ChevronLeft size={18}/></button><button type="button" onClick={()=>setActive((active+1)%items.length)} className="flex h-10 w-10 items-center justify-center bg-[#222B52] text-[#F8F8F5]" data-testid="button-testimonial-next"><ChevronRight size={18}/></button><span className="ml-3 text-[10px] font-bold uppercase tracking-[.15em] text-[#6B7280]">{String(active+1).padStart(2,'0')} / {String(items.length).padStart(2,'0')}</span></div></div></div></div></section></PublicShell>;
}

function FaqPage() {
  const [open, setOpen] = useState(0); const [query, setQuery] = useState('');
  const visible = seedFaqs.filter(([q,a]) => `${q} ${a}`.toLowerCase().includes(query.toLowerCase()));
  return <PublicShell><PageIntro eyebrow="FAQ" title={<>The useful answers, before <em>the first meeting.</em></>} copy="Costs, inclusions, timelines and the practical details that make a construction conversation more useful." /><section className="section-pad bg-[#FFF]"><div className="site-shell max-w-[920px]"><label className="mb-10 flex items-center gap-3 border-b border-[#222B52]/25 pb-4"><Search size={17} className="text-[#0C4A46]"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search costs, materials, warranty..." className="w-full bg-transparent text-sm outline-none" data-testid="input-faq-search"/></label>{visible.map(([question,answer],index)=><div key={question} className="border-t border-[#222B52]/15"><button type="button" onClick={()=>setOpen(open===index?-1:index)} className="flex w-full items-center justify-between py-7 text-left" data-testid={`button-faq-${index}`}><span className="font-editorial text-3xl text-[#222B52]">{question}</span><ChevronDown size={19} className={`text-[#0C4A46] transition-transform ${open===index?'rotate-180':''}`}/></button><div className={`faq-answer ${open===index?'open':''}`}><div><p className="max-w-[700px] pb-7 text-sm leading-7 text-[#6B7280]">{answer}</p></div></div></div>)}{!visible.length&&<p className="py-12 text-sm text-[#6B7280]">No answers found. Try a different phrase or send us your question.</p>}</div></section><section className="bg-[#0C4A46] py-16 text-[#F8F8F5]"><div className="site-shell flex flex-col justify-between gap-6 md:flex-row md:items-center"><h2 className="font-editorial text-5xl">Still deciding?</h2><Button href="/contact" inverse>Ask Nestood</Button></div></section></PublicShell>;
}

function BlogPage() {
  const [items] = useStored<Blog[]>('nestood_blogs', seedBlogs); const [category, setCategory] = useState('All');
  const cats = ['All', ...Array.from(new Set(items.map(item=>item.category)))]; const visible=items.filter(item=>category==='All'||item.category===category);
  return <PublicShell><PageIntro eyebrow="Journal" title={<>A practical knowledge <em>centre.</em></>} copy="Real notes on costs, materials, planning and the local decisions that shape a construction project." /><section className="section-pad bg-[#F8F8F5]"><div className="site-shell"><div className="flex flex-wrap gap-2">{cats.map(cat=><button type="button" key={cat} onClick={()=>setCategory(cat)} className={`border px-4 py-2 text-[10px] font-bold uppercase tracking-[.14em] ${category===cat?'border-[#222B52] bg-[#222B52] text-[#F8F8F5]':'border-[#222B52]/20 text-[#6B7280]'}`} data-testid={`button-blog-filter-${cat.toLowerCase().replace(' ','-')}`}>{cat}</button>)}</div><div className="mt-12 grid gap-6 md:grid-cols-2 lg:grid-cols-3">{visible.map((post,i)=><Link href={`/blog/${post.slug}`} key={post.id} className={`group border-t border-[#222B52]/20 pt-6 ${i===0&&category==='All'?'md:col-span-2':''}`} data-testid={`card-blog-${post.id}`}><Visual label={post.category} name={post.title} className={i===0&&category==='All'?'min-h-[310px]':''}/><p className="mt-6 text-sm leading-6 text-[#6B7280]">{post.excerpt}</p><span className="mt-5 inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]">Read note <ArrowUpRight size={15}/></span></Link>)}</div></div></section></PublicShell>;
}
function BlogDetailPage() {
  const { slug } = useParams<{slug:string}>(); const [items]=useStored<Blog[]>('nestood_blogs',seedBlogs); const post=items.find(item=>item.slug===slug)??seedBlogs[0];
  return <PublicShell><section className="bg-[#222B52] pb-20 pt-36 text-[#F8F8F5]"><div className="site-shell max-w-[900px]"><Link href="/blog" className="inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.16em] text-[#A5C7C1]" data-testid="link-back-blog"><ArrowLeft size={15}/> Back to journal</Link><p className="mt-16 text-[10px] font-bold uppercase tracking-[.18em] text-[#A5C7C1]">{post.category}</p><h1 className="mt-5 font-editorial text-[clamp(4rem,8vw,7.5rem)] leading-[.82]">{post.title}</h1><p className="mt-8 max-w-[620px] text-lg leading-8 text-[#F8F8F5]/65">{post.excerpt}</p></div></section><article className="section-pad bg-[#FFF]"><div className="site-shell grid gap-12 lg:grid-cols-[.35fr_1fr]"><aside><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#0C4A46]">A Nestood note</p><p className="mt-4 text-sm text-[#6B7280]">Written for people making a serious decision about a place.</p></aside><div className="max-w-[680px]"><p className="font-editorial text-4xl leading-tight text-[#222B52]">{post.body.split('. ')[0]}.</p><div className="mt-9 space-y-5 text-[16px] leading-8 text-[#6B7280]"><p>{post.body}</p><p>A good project is not the sum of isolated choices. It is a chain of decisions that stay connected — from the first site measure to the final clean, from the budget line to the hand on a door.</p></div><Button href="/contact">Talk to a construction partner</Button></div></div></article></PublicShell>;
}

function ContactPage() {
  const [sent,setSent]=useState(false);
  const [form,setForm]=useState({name:'',mobile:'',email:'',location:'Chennai',constructionType:'Individual home',plotSize:'',builtArea:'',budget:'',timeline:'',message:''});
  const update=(key:string,value:string)=>setForm({...form,[key]:value});
  function submit(event:FormEvent){event.preventDefault(); const existing=readStore<Enquiry[]>('nestood_enquiries',[]); const enquiry:Enquiry={...form,id:`enq-${Date.now()}`,created:new Date().toISOString(),source:'Contact form',status:'New',assigned:'Unassigned',notes:'',followUp:''}; localStorage.setItem('nestood_enquiries',JSON.stringify([enquiry,...existing]));setSent(true);}
  const fields=[['name','Name','text'],['mobile','Mobile number','tel'],['email','Email','email'],['location','Site location','text'],['constructionType','Construction type','text'],['plotSize','Plot size','text'],['builtArea','Built-up area','text'],['budget','Budget range','text'],['timeline','Preferred timeline','text']];
  return <PublicShell><PageIntro eyebrow="Contact" title={<>Bring us the first <em>line.</em></>} copy="Tell us enough to make a first conversation useful. We will come back with the right questions, not a generic brochure." dark /><section className="section-pad bg-[#F8F8F5]"><div className="site-shell grid gap-12 lg:grid-cols-[1.25fr_.75fr]"><form onSubmit={submit} className="bg-[#FFF] p-6 sm:p-10"><div className="grid gap-6 sm:grid-cols-2">{fields.map(([key,label,type])=><label key={key} className="block"><span className="mb-2 block text-[10px] font-bold uppercase tracking-[.14em] text-[#6B7280]">{label}</span><input required={key==='name'||key==='mobile'||key==='email'} type={type} value={form[key as keyof typeof form]} onChange={e=>update(key,e.target.value)} className="admin-input" data-testid={`input-contact-${key}`}/></label>)}</div><label className="mt-6 block"><span className="mb-2 block text-[10px] font-bold uppercase tracking-[.14em] text-[#6B7280]">Message</span><textarea value={form.message} onChange={e=>update('message',e.target.value)} rows={5} className="admin-input resize-y" placeholder="What would you like to make?" data-testid="textarea-contact-message"/></label>{sent?<div className="mt-7 flex items-start gap-3 border border-[#0C4A46]/30 bg-[#F8F8F5] p-5 text-sm leading-6 text-[#0C4A46]" data-testid="status-contact-success"><Check size={18}/> Thank you. Your enquiry is saved and our team will be in touch.</div>:<button type="submit" className="mt-7 inline-flex items-center gap-3 bg-[#222B52] px-5 py-4 text-[10px] font-bold uppercase tracking-[.16em] text-[#F8F8F5]" data-testid="button-contact-submit">Send enquiry <Send size={16}/></button>}</form><aside><div className="border-t border-[#222B52]/20 pt-6"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#0C4A46]">Prefer a direct line?</p><a href="tel:+919840012345" className="mt-5 flex items-center gap-3 font-editorial text-3xl text-[#222B52]" data-testid="link-contact-call"><Phone size={18} className="text-[#0C4A46]"/> +91 98400 12345</a><a href="https://wa.me/919840012345" className="mt-4 flex items-center gap-3 text-sm text-[#0C4A46]" data-testid="link-contact-whatsapp"><MessageCircle size={17}/> Message us on WhatsApp</a></div><div className="mt-12 border-t border-[#222B52]/20 pt-6"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#0C4A46]">Studio</p><p className="mt-4 text-sm leading-6 text-[#6B7280]">14, Kotturpuram High Road<br/>Chennai 600085<br/><br/>Mon–Sat · 9:30 am–6:30 pm</p><a href="https://maps.google.com/?q=Kotturpuram+Chennai" className="mt-5 inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]" data-testid="link-contact-map"><MapPin size={15}/> Open in Google Maps</a></div><div className="mt-12 border-t border-[#222B52]/20 pt-6"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#0C4A46]">Social</p><div className="mt-4 flex gap-5 text-sm text-[#6B7280]"><a href="https://instagram.com" data-testid="link-contact-instagram">Instagram</a><a href="https://linkedin.com" data-testid="link-contact-linkedin">LinkedIn</a></div></div></aside></div></section></PublicShell>;
}

function CalculatorPage() {
  const [settings]=useStored('nestood_calculator_settings',defaultSettings); const [location,setLocation]=useState('Chennai'); const [type,setType]=useState(settings.types[0]); const [area,setArea]=useState(2200); const [floors,setFloors]=useState(2); const [packageName,setPackageName]=useState('Standard'); const [additions,setAdditions]=useState<string[]>([]); const [captured,setCaptured]=useState(false); const [lead,setLead]=useState({name:'',mobile:'',email:''});
  const packageRate=seedPackages.find(pkg=>pkg.name===packageName)?.rate??2650; const baseRate=(settings.rates[type]??packageRate)+(settings.locations[location]??0); const estimate=Math.round(area*baseRate*(floors>2?1.08:1)+(additions.reduce((sum,item)=>sum+(settings.additions[item]??0),0)*area)); const format=(amount:number)=>`₹${(amount/10000000).toFixed(2)} Cr`;
  function capture(event:FormEvent){event.preventDefault(); const existing=readStore<Enquiry[]>('nestood_enquiries',[]); const enquiry:Enquiry={id:`calc-${Date.now()}`,created:new Date().toISOString(),name:lead.name,mobile:lead.mobile,email:lead.email,location,constructionType:type,plotSize:'',builtArea:`${area} sq ft`,budget:format(estimate),timeline:'To discuss',message:`Calculator package: ${packageName}; additions: ${additions.join(', ')||'None'}`,source:'Cost calculator',status:'New',assigned:'Unassigned',notes:'',followUp:''};localStorage.setItem('nestood_enquiries',JSON.stringify([enquiry,...existing]));setCaptured(true);}
  return <PublicShell><PageIntro eyebrow="Calculator" title={<>Start with a sense of <em>scale.</em></>} copy="A useful first range, not a promise. Change the brief and see how the number moves. Then save it with your details for a considered follow-up." /><section className="section-pad bg-[#FFF]"><div className="site-shell grid gap-10 lg:grid-cols-[.75fr_1.25fr]"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#0C4A46]">Construction cost calculator</p><h2 className="mt-6 font-editorial text-6xl leading-[.88] text-[#222B52]">Your early<br /><em>estimate.</em></h2><p className="mt-7 max-w-[350px] text-sm leading-7 text-[#6B7280]">Rates are controlled from the local admin settings and exclude land, taxes and statutory fees.</p><div className="mt-10 flex items-center gap-3 text-[10px] font-bold uppercase tracking-[.14em] text-[#0C4A46]"><Ruler size={17}/> Updated from Nestood rates</div></div><div className="border border-[#222B52]/15 bg-[#F8F8F5] p-6 sm:p-10"><div className="grid gap-7 sm:grid-cols-2"><label><span className="mb-2 block text-[10px] font-bold uppercase tracking-[.13em] text-[#6B7280]">Location</span><select value={location} onChange={e=>setLocation(e.target.value)} className="admin-input" data-testid="select-calculator-location"><option>Chennai</option><option>Bengaluru</option></select></label><label><span className="mb-2 block text-[10px] font-bold uppercase tracking-[.13em] text-[#6B7280]">Construction type</span><select value={type} onChange={e=>setType(e.target.value)} className="admin-input" data-testid="select-calculator-type">{settings.types.map(item=><option key={item}>{item}</option>)}</select></label></div><label className="mt-8 block"><div className="mb-3 flex justify-between text-[10px] font-bold uppercase tracking-[.13em] text-[#6B7280]"><span>Built-up area</span><span className="text-[#222B52]">{area.toLocaleString()} sq ft</span></div><input type="range" min="600" max="10000" step="100" value={area} onChange={e=>setArea(Number(e.target.value))} className="estimate-range h-1 w-full" data-testid="input-calculator-area"/><div className="mt-2 flex justify-between text-[10px] text-[#6B7280]"><span>600 sq ft</span><span>10,000 sq ft</span></div></label><div className="mt-8 grid gap-7 sm:grid-cols-2"><label><span className="mb-2 block text-[10px] font-bold uppercase tracking-[.13em] text-[#6B7280]">Number of floors</span><select value={floors} onChange={e=>setFloors(Number(e.target.value))} className="admin-input" data-testid="select-calculator-floors"><option value={1}>1 floor</option><option value={2}>2 floors</option><option value={3}>3 floors</option><option value={4}>4 floors</option></select></label><label><span className="mb-2 block text-[10px] font-bold uppercase tracking-[.13em] text-[#6B7280]">Package</span><select value={packageName} onChange={e=>setPackageName(e.target.value)} className="admin-input" data-testid="select-calculator-package">{seedPackages.map(pkg=><option key={pkg.id}>{pkg.name}</option>)}</select></label></div><div className="mt-8"><span className="mb-3 block text-[10px] font-bold uppercase tracking-[.13em] text-[#6B7280]">Additional allowances</span><div className="flex flex-wrap gap-2">{Object.keys(settings.additions).map(item=><button type="button" key={item} onClick={()=>setAdditions(additions.includes(item)?additions.filter(value=>value!==item):[...additions,item])} className={`border px-3 py-2 text-[10px] font-bold uppercase tracking-[.1em] ${additions.includes(item)?'border-[#0C4A46] bg-[#0C4A46] text-[#F8F8F5]':'border-[#222B52]/20 text-[#6B7280]'}`} data-testid={`button-calculator-addition-${item.replace(' ','-').toLowerCase()}`}>{item}</button>)}</div></div><div className="mt-9 border-t border-[#222B52]/15 pt-6"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#6B7280]">Indicative construction range</p><p className="mt-2 font-editorial text-6xl text-[#0C4A46]" data-testid="text-calculator-estimate">{format(estimate)}</p><p className="mt-3 text-xs text-[#6B7280]">₹{baseRate.toLocaleString()} blended rate · {area.toLocaleString()} sq ft</p></div>{captured?<div className="mt-8 border border-[#0C4A46]/30 bg-[#FFF] p-5 text-sm leading-6 text-[#0C4A46]" data-testid="status-calculator-success"><Check size={17} className="mr-2 inline"/> Estimate saved. Our team will reach out with the right next questions.</div>:<form onSubmit={capture} className="mt-8 border-t border-[#222B52]/15 pt-7"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]">Save this estimate</p><div className="mt-5 grid gap-4 sm:grid-cols-3"><input required placeholder="Name" value={lead.name} onChange={e=>setLead({...lead,name:e.target.value})} className="admin-input" data-testid="input-calculator-name"/><input required placeholder="Mobile" value={lead.mobile} onChange={e=>setLead({...lead,mobile:e.target.value})} className="admin-input" data-testid="input-calculator-mobile"/><input required type="email" placeholder="Email" value={lead.email} onChange={e=>setLead({...lead,email:e.target.value})} className="admin-input" data-testid="input-calculator-email"/></div><button type="submit" className="mt-5 flex w-full items-center justify-between bg-[#222B52] px-5 py-4 text-left text-[10px] font-bold uppercase tracking-[.15em] text-[#F8F8F5]" data-testid="button-calculator-save">Save and request a follow-up <ArrowUpRight size={17}/></button></form>}</div></div></section></PublicShell>;
}

function AdminShell({ children }: { children: ReactNode }) {
  const [,setLocation]=useLocation(); const links=[['Overview','/admin',LayoutDashboard],['Leads','/admin/leads',Users],['Projects','/admin/projects',Building2],['Packages','/admin/packages',ClipboardList],['Services','/admin/services',Hammer],['Testimonials','/admin/testimonials',Star],['Locations','/admin/locations',MapPin],['Blog','/admin/blog',Mail],['Calculator','/admin/calculator',Settings2]] as const;
  return <div className="min-h-[100dvh] bg-[#F8F8F5] text-[#222B52]"><aside className="fixed inset-y-0 left-0 z-40 hidden w-[245px] flex-col bg-[#222B52] p-6 text-[#F8F8F5] lg:flex"><Brand inverse/><p className="mt-14 text-[10px] font-bold uppercase tracking-[.18em] text-[#A5C7C1]">Studio admin</p><nav className="mt-5 flex flex-col gap-1">{links.map(([label,href,Icon])=><Link href={href} key={href} className="flex items-center gap-3 px-3 py-3 text-xs text-[#F8F8F5]/65 hover:bg-[#2d3860] hover:text-[#F8F8F5]" data-testid={`link-admin-${label.toLowerCase()}`}><Icon size={16}/>{label}</Link>)}</nav><Link href="/" className="mt-auto flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#A5C7C1]" data-testid="link-admin-view-site"><ArrowLeft size={15}/> View website</Link></aside><div className="lg:pl-[245px]"><header className="flex h-[76px] items-center justify-between border-b border-[#222B52]/10 bg-[#FFF] px-5 sm:px-9"><div className="lg:hidden"><Brand/></div><div className="hidden text-[10px] font-bold uppercase tracking-[.18em] text-[#6B7280] lg:block">Nestood / Local content studio</div><button type="button" onClick={()=>setLocation('/')} className="text-[10px] font-bold uppercase tracking-[.15em] text-[#0C4A46]" data-testid="button-admin-exit">Exit admin <ArrowUpRight size={15} className="ml-1 inline"/></button></header><main className="p-5 sm:p-9">{children}</main></div></div>;
}
function AdminHeading({ eyebrow,title,action,onClick }: {eyebrow:string;title:string;action?:string;onClick?:()=>void}) { return <div className="mb-10 flex flex-col justify-between gap-5 border-b border-[#222B52]/15 pb-7 sm:flex-row sm:items-end"><div><p className="text-[10px] font-bold uppercase tracking-[.18em] text-[#0C4A46]">{eyebrow}</p><h1 className="mt-3 font-editorial text-6xl leading-[.87]">{title}</h1></div>{action&&<button type="button" onClick={onClick} className="inline-flex items-center gap-2 bg-[#0C4A46] px-4 py-3 text-[10px] font-bold uppercase tracking-[.15em] text-[#F8F8F5]" data-testid="button-admin-add"><Plus size={16}/>{action}</button>}</div>; }
function AdminDashboard() {
  const [leads]=useStored<Enquiry[]>('nestood_enquiries',[]); const [projects]=useStored<Project[]>('nestood_projects',seedProjects);
  const newLeads=leads.filter(item=>item.status==='New').length; const converted=leads.filter(item=>item.status==='Converted').length;
  const stats: {label:string; value:number; icon:typeof Mail}[] = [{label:'Total enquiries',value:leads.length,icon:Mail},{label:'New enquiries',value:newLeads,icon:Send},{label:'Converted leads',value:converted,icon:Check},{label:'Projects in library',value:projects.length,icon:Building2}];
  return <AdminShell><AdminHeading eyebrow="Overview / 01" title="Good morning."/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map(stat=><div key={stat.label} className="border border-[#222B52]/15 bg-[#FFF] p-6"><stat.icon size={18} className="text-[#0C4A46]"/><p className="mt-8 font-editorial text-5xl">{stat.value}</p><p className="mt-2 text-[10px] font-bold uppercase tracking-[.14em] text-[#6B7280]">{stat.label}</p></div>)}</div><div className="mt-10 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="border border-[#222B52]/15 bg-[#FFF] p-6"><div className="flex justify-between"><h2 className="font-editorial text-3xl">Latest enquiries</h2><Link href="/admin/leads" className="text-[10px] font-bold uppercase tracking-[.14em] text-[#0C4A46]" data-testid="link-dashboard-leads">View all</Link></div>{leads.slice(0,5).map(lead=><div key={lead.id} className="flex items-center justify-between border-t border-[#222B52]/10 py-4"><div><p className="text-sm font-semibold">{lead.name}</p><p className="mt-1 text-xs text-[#6B7280]">{lead.source} · {lead.location}</p></div><span className="text-[10px] font-bold uppercase tracking-[.1em] text-[#0C4A46]">{lead.status}</span></div>)}{!leads.length&&<p className="mt-8 text-sm text-[#6B7280]">No enquiries yet. The public contact and calculator forms will appear here.</p>}</div><div className="border border-[#222B52]/15 bg-[#FFF] p-6"><h2 className="font-editorial text-3xl">Quick links</h2><div className="mt-7 grid gap-2">{[['Add a project','/admin/projects'],['Update package rates','/admin/packages'],['Write a journal note','/admin/blog'],['Review calculator','/admin/calculator']].map(([label,href])=><Link href={href} key={href} className="flex items-center justify-between border-b border-[#222B52]/10 py-4 text-sm" data-testid={`link-dashboard-${href.split('/').pop()}`}>{label}<ArrowUpRight size={16} className="text-[#0C4A46]"/></Link>)}</div></div></div></AdminShell>;
}
function AdminLeadsPage() {
  const [leads,setLeads]=useStored<Enquiry[]>('nestood_enquiries',[]); const [filter,setFilter]=useState('All'); const statuses=['New','Contacted','Qualified','Site Visit','Proposal Sent','Converted','Lost']; const visible=leads.filter(item=>filter==='All'||item.status===filter);
  const patch=(id:string,key:string,value:string)=>setLeads(leads.map(item=>item.id===id?{...item,[key]:value}:item));
  return <AdminShell><AdminHeading eyebrow="Sales / 02" title="Enquiries."/><div className="mb-7 flex flex-wrap gap-2"><select value={filter} onChange={e=>setFilter(e.target.value)} className="admin-input max-w-[220px]" data-testid="select-leads-filter"><option>All</option>{statuses.map(item=><option key={item}>{item}</option>)}</select><span className="flex items-center px-3 text-xs text-[#6B7280]">{visible.length} records</span></div><div className="space-y-4">{visible.map(lead=><article key={lead.id} className="border border-[#222B52]/15 bg-[#FFF] p-5 sm:p-7"><div className="flex flex-col justify-between gap-4 sm:flex-row"><div><div className="flex items-center gap-3"><h2 className="font-editorial text-3xl">{lead.name}</h2><span className="text-[10px] uppercase tracking-[.12em] text-[#6B7280]">{lead.source}</span></div><p className="mt-2 text-sm text-[#6B7280]">{lead.mobile} · {lead.email} · {lead.location}</p></div><select value={lead.status} onChange={e=>patch(lead.id,'status',e.target.value)} className="admin-input max-w-[190px]" data-testid={`select-lead-status-${lead.id}`}>{statuses.map(item=><option key={item}>{item}</option>)}</select></div><div className="mt-6 grid gap-5 border-t border-[#222B52]/10 pt-5 sm:grid-cols-4"><div><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#6B7280]">Brief</p><p className="mt-2 text-sm">{lead.constructionType} · {lead.builtArea||'Area not given'}</p></div><div><p className="text-[10px] font-bold uppercase tracking-[.12em] text-[#6B7280]">Budget / timeline</p><p className="mt-2 text-sm">{lead.budget||'Not given'} · {lead.timeline||'Not given'}</p></div><label><span className="text-[10px] font-bold uppercase tracking-[.12em] text-[#6B7280]">Assign</span><select value={lead.assigned} onChange={e=>patch(lead.id,'assigned',e.target.value)} className="admin-input mt-2 py-2 text-xs" data-testid={`select-lead-assignee-${lead.id}`}><option>Unassigned</option><option>Priya Nair</option><option>Vikram Shah</option><option>Leena Thomas</option></select></label><label><span className="text-[10px] font-bold uppercase tracking-[.12em] text-[#6B7280]">Follow up</span><input type="date" value={lead.followUp} onChange={e=>patch(lead.id,'followUp',e.target.value)} className="admin-input mt-2 py-2 text-xs" data-testid={`input-lead-followup-${lead.id}`}/></label></div><label className="mt-5 block"><span className="text-[10px] font-bold uppercase tracking-[.12em] text-[#6B7280]">Internal notes</span><textarea value={lead.notes} onChange={e=>patch(lead.id,'notes',e.target.value)} rows={2} className="admin-input mt-2 text-sm" data-testid={`textarea-lead-notes-${lead.id}`}/></label></article>)}{!visible.length&&<div className="border border-dashed border-[#222B52]/20 py-16 text-center text-sm text-[#6B7280]">No enquiries in this status.</div>}</div></AdminShell>;
}
const adminConfig: Record<string,{title:string; eyebrow:string; storage:string; seed:AnyRecord[]; fields:{key:string;label:string;type?:string}[]}> = {
  projects:{title:'Projects.',eyebrow:'Content / 03',storage:'nestood_projects',seed:seedProjects as unknown as AnyRecord[],fields:[{key:'name',label:'Name'},{key:'slug',label:'Slug'},{key:'category',label:'Category'},{key:'status',label:'Status'},{key:'location',label:'Location'},{key:'area',label:'Area'},{key:'cost',label:'Cost'},{key:'completion',label:'Completion'},{key:'description',label:'Description',type:'textarea'},{key:'specs',label:'Specifications',type:'textarea'},{key:'imageMetadata',label:'Image metadata / CSS fallback'}]},
  packages:{title:'Packages.',eyebrow:'Pricing / 04',storage:'nestood_packages',seed:seedPackages as unknown as AnyRecord[],fields:[{key:'name',label:'Name'},{key:'rate',label:'Price per sq ft',type:'number'},{key:'summary',label:'Summary',type:'textarea'},{key:'inclusions',label:'Inclusions',type:'textarea'},{key:'materials',label:'Materials',type:'textarea'},{key:'specs',label:'Specifications',type:'textarea'},{key:'exclusions',label:'Exclusions',type:'textarea'}]},
  services:{title:'Services.',eyebrow:'Content / 05',storage:'nestood_services',seed:seedServices as unknown as AnyRecord[],fields:[{key:'title',label:'Title'},{key:'category',label:'Category'},{key:'description',label:'Description',type:'textarea'},{key:'inclusions',label:'Inclusions',type:'textarea'},{key:'process',label:'Process',type:'textarea'},{key:'materials',label:'Materials',type:'textarea'},{key:'pricing',label:'Pricing'},{key:'faqs',label:'FAQs (separate with ||)',type:'textarea'},{key:'imageMetadata',label:'Image metadata / CSS fallback'}]},
  testimonials:{title:'Testimonials.',eyebrow:'Content / 06',storage:'nestood_testimonials',seed:seedTestimonials as unknown as AnyRecord[],fields:[{key:'customer',label:'Customer'},{key:'project',label:'Project'},{key:'location',label:'Location'},{key:'rating',label:'Rating',type:'number'},{key:'review',label:'Review',type:'textarea'},{key:'media',label:'Photo / video metadata'}]},
  locations:{title:'Locations.',eyebrow:'Local SEO / 07',storage:'nestood_locations',seed:seedLocations as unknown as AnyRecord[],fields:[{key:'city',label:'City'},{key:'areas',label:'Areas served',type:'textarea'},{key:'pricing',label:'Local pricing'},{key:'services',label:'Services',type:'textarea'},{key:'description',label:'Location page description',type:'textarea'}]},
  blog:{title:'Journal.',eyebrow:'SEO content / 08',storage:'nestood_blogs',seed:seedBlogs as unknown as AnyRecord[],fields:[{key:'title',label:'Title'},{key:'slug',label:'Slug'},{key:'category',label:'Category'},{key:'excerpt',label:'Excerpt',type:'textarea'},{key:'body',label:'Body',type:'textarea'},{key:'featured',label:'Featured (true / false)'},{key:'seoTitle',label:'SEO title'},{key:'meta',label:'Meta description'}]},
};
function AdminContentPage({ kind }: {kind:string}) {
  const config=adminConfig[kind]; const [items,setItems]=useStored<AnyRecord[]>(config.storage,config.seed); const [editing,setEditing]=useState<AnyRecord|null>(null);
  const blank=()=>Object.fromEntries(config.fields.map(field=>[field.key,field.type==='number'?0:''])) as AnyRecord;
  const save=(event:FormEvent)=>{event.preventDefault();if(!editing)return;const item={...editing,id:editing.id||`${kind}-${Date.now()}`};setItems(editing.id?items.map(existing=>existing.id===editing.id?item:existing):[...items,item]);setEditing(null);};
  const remove=(id:unknown)=>{if(window.confirm('Delete this item?'))setItems(items.filter(item=>item.id!==id));};
  return <AdminShell><AdminHeading eyebrow={config.eyebrow} title={config.title} action="Add new" onClick={()=>setEditing(blank())}/><div className="grid gap-4">{items.map(item=><article key={String(item.id)} className="flex flex-col justify-between gap-5 border border-[#222B52]/15 bg-[#FFF] p-6 sm:flex-row sm:items-center"><div><p className="font-editorial text-3xl">{String(item.title??item.name??item.customer??item.city??'Untitled')}</p><p className="mt-2 max-w-[680px] text-sm text-[#6B7280]">{String(item.description??item.excerpt??item.review??item.summary??item.pricing??'')}</p></div><div className="flex shrink-0 gap-2"><button type="button" onClick={()=>setEditing({...item})} className="flex h-10 w-10 items-center justify-center border border-[#222B52]/20 text-[#0C4A46]" aria-label="Edit" data-testid={`button-admin-edit-${item.id}`}><Pencil size={16}/></button><button type="button" onClick={()=>remove(item.id)} className="flex h-10 w-10 items-center justify-center border border-[#222B52]/20 text-[#6B7280]" aria-label="Delete" data-testid={`button-admin-delete-${item.id}`}><Trash2 size={16}/></button></div></article>)}</div>{editing&&<div className="fixed inset-0 z-50 flex items-end justify-center bg-[#000]/45 p-4 sm:items-center"><form onSubmit={save} className="max-h-[92dvh] w-full max-w-3xl overflow-y-auto bg-[#F8F8F5] p-6 sm:p-9"><div className="flex items-start justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#0C4A46]">Edit content</p><h2 className="mt-2 font-editorial text-4xl">{editing.id?'Update':'Create'} {kind}</h2></div><button type="button" onClick={()=>setEditing(null)} className="text-[#6B7280]" data-testid="button-admin-close"><X size={20}/></button></div><div className="mt-8 grid gap-5 sm:grid-cols-2">{config.fields.map(field=><label key={field.key} className={field.type==='textarea'?'sm:col-span-2':''}><span className="mb-2 block text-[10px] font-bold uppercase tracking-[.13em] text-[#6B7280]">{field.label}</span>{field.type==='textarea'?<textarea rows={4} value={String(editing[field.key]??'')} onChange={e=>setEditing({...editing,[field.key]:e.target.value})} className="admin-input" data-testid={`textarea-admin-${field.key}`}/>:<input type={field.type==='number'?'number':'text'} value={String(editing[field.key]??'')} onChange={e=>setEditing({...editing,[field.key]:field.type==='number'?Number(e.target.value):e.target.value})} className="admin-input" data-testid={`input-admin-${field.key}`}/>}</label>)}</div><button type="submit" className="mt-8 flex items-center gap-3 bg-[#0C4A46] px-5 py-4 text-[10px] font-bold uppercase tracking-[.15em] text-[#F8F8F5]" data-testid="button-admin-save">Save changes <Check size={16}/></button></form></div>}</AdminShell>;
}
function AdminCalculatorPage() {
  const [settings,setSettings]=useStored('nestood_calculator_settings',defaultSettings); const [newType,setNewType]=useState(''); const [newAdd,setNewAdd]=useState('');
  const updateRate=(type:string,value:string)=>setSettings({...settings,rates:{...settings.rates,[type]:Number(value)}}); const addType=()=>{if(newType&&!settings.types.includes(newType))setSettings({...settings,types:[...settings.types,newType],rates:{...settings.rates,[newType]:2000}});setNewType('');}; const addAddition=()=>{if(newAdd&&!settings.additions[newAdd])setSettings({...settings,additions:{...settings.additions,[newAdd]:50}});setNewAdd('');};
  return <AdminShell><AdminHeading eyebrow="Calculator / 09" title="Rates that stay current."/><div className="grid gap-5 lg:grid-cols-2"><section className="border border-[#222B52]/15 bg-[#FFF] p-6"><h2 className="font-editorial text-3xl">Construction types</h2><div className="mt-6 space-y-3">{settings.types.map(type=><label key={type} className="flex items-center gap-3"><span className="flex-1 text-sm">{type}</span><input type="number" value={settings.rates[type]??0} onChange={e=>updateRate(type,e.target.value)} className="admin-input max-w-[150px]" data-testid={`input-rate-${type}`}/><span className="text-xs text-[#6B7280]">/ sq ft</span></label>)}</div><div className="mt-7 flex gap-2 border-t border-[#222B52]/10 pt-5"><input value={newType} onChange={e=>setNewType(e.target.value)} placeholder="New construction type" className="admin-input" data-testid="input-new-construction-type"/><button type="button" onClick={addType} className="bg-[#0C4A46] px-4 text-[#F8F8F5]" data-testid="button-add-construction-type"><Plus size={17}/></button></div></section><section className="border border-[#222B52]/15 bg-[#FFF] p-6"><h2 className="font-editorial text-3xl">Location adjustments</h2><div className="mt-6 space-y-3">{Object.keys(settings.locations).map(city=><label key={city} className="flex items-center gap-3"><span className="flex-1 text-sm">{city}</span><input type="number" value={settings.locations[city]} onChange={e=>setSettings({...settings,locations:{...settings.locations,[city]:Number(e.target.value)}})} className="admin-input max-w-[150px]" data-testid={`input-location-rate-${city}`}/><span className="text-xs text-[#6B7280]">adjustment</span></label>)}</div><h2 className="mt-10 border-t border-[#222B52]/10 pt-6 font-editorial text-3xl">Additional charges</h2><div className="mt-5 space-y-3">{Object.keys(settings.additions).map(item=><label key={item} className="flex items-center gap-3"><span className="flex-1 text-sm">{item}</span><input type="number" value={settings.additions[item]} onChange={e=>setSettings({...settings,additions:{...settings.additions,[item]:Number(e.target.value)}})} className="admin-input max-w-[150px]" data-testid={`input-additional-rate-${item}`}/><span className="text-xs text-[#6B7280]">/ sq ft</span></label>)}</div><div className="mt-7 flex gap-2 border-t border-[#222B52]/10 pt-5"><input value={newAdd} onChange={e=>setNewAdd(e.target.value)} placeholder="New allowance" className="admin-input" data-testid="input-new-additional"/><button type="button" onClick={addAddition} className="bg-[#0C4A46] px-4 text-[#F8F8F5]" data-testid="button-add-additional"><Plus size={17}/></button></div></section></div><p className="mt-7 flex items-center gap-2 text-xs text-[#0C4A46]"><Check size={15}/> Changes save automatically to localStorage and update the public calculator.</p></AdminShell>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><ErrorBoundary><WouterRouter><Switch><Route path="/" component={HomePage}/><Route path="/about" component={AboutPage}/><Route path="/services" component={ServicesPage}/><Route path="/packages" component={PackagesPage}/><Route path="/projects" component={ProjectsPage}/><Route path="/projects/:slug" component={ProjectDetailPage}/><Route path="/locations" component={LocationsPage}/><Route path="/testimonials" component={TestimonialsPage}/><Route path="/faq" component={FaqPage}/><Route path="/blog" component={BlogPage}/><Route path="/blog/:slug" component={BlogDetailPage}/><Route path="/contact" component={ContactPage}/><Route path="/calculator" component={CalculatorPage}/><Route path="/admin" component={AdminDashboard}/><Route path="/admin/leads" component={AdminLeadsPage}/><Route path="/admin/projects">{()=><AdminContentPage kind="projects"/>}</Route><Route path="/admin/packages">{()=><AdminContentPage kind="packages"/>}</Route><Route path="/admin/services">{()=><AdminContentPage kind="services"/>}</Route><Route path="/admin/testimonials">{()=><AdminContentPage kind="testimonials"/>}</Route><Route path="/admin/locations">{()=><AdminContentPage kind="locations"/>}</Route><Route path="/admin/blog">{()=><AdminContentPage kind="blog"/>}</Route><Route path="/admin/calculator" component={AdminCalculatorPage}/><Route component={NotFound}/></Switch></WouterRouter></ErrorBoundary><Toaster/></TooltipProvider></QueryClientProvider>;
}

export default App;